mkdir -p /tmp/pricecheck && cat > /tmp/pricecheck/check.py <<'EOF'
import csv, sys
from decimal import Decimal, ROUND_HALF_UP
sys.path.insert(0, sys.argv[1])
import price as p

# Build zone x band matrix of final prices, rounded once per cell
matrix = {}
for z, base in p.ZONES.items():
    for band, lo, hi, m in p.BANDS:
        v = base * m
        if z in p.REMOTE_ZONES and band in p.HEAVY_BANDS:
            v += p.REMOTE_HEAVY_SURCHARGE
        matrix[z, band] = v.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

print("zone," + ",".join(b for b, *_ in p.BANDS))
for z in p.ZONES:
    print(z + "," + ",".join(str(matrix[z, b]) for b, *_ in p.BANDS))

mism = errs = 0; total = Decimal(0)
with open(sys.argv[1] + "/orders_2026-09.csv") as f:
    for r in csv.DictReader(f):
        w = float(r["weight_kg"])
        try:
            old = p.price(r["zone"], w)
        except Exception as e:
            errs += 1; print("ERR", r, e); continue
        new = matrix[r["zone"], p.band_for(w)]
        total += old
        if old != new: mism += 1; print("MISMATCH", r, old, new)
print("mismatches", mism, "errors", errs, "total", total)
EOF
